:root {
  --bg:#f6f7f9; --card:#fff; --ink:#1c2330; --muted:#6b7480; --line:#e6e9ee;
  --accent:#2f6df6; --flash:#fff6d6; --chip:#eef1f6; --chipink:#3a4658; --mark:#fff1a8;
  --read:#2a9d55; --danger:#c0392b; --warn:#c9791f; --warnbg:#fdf2e3; --note:#5a4a1f; --notebg:#fbf6e6;
}
* { box-sizing:border-box; }
body { margin:0; background:var(--bg); color:var(--ink);
  font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; }
.wrap { max-width:740px; margin:0 auto; padding:38px 20px 100px; }
h1 { font-size:22px; margin:0 0 4px; } .sub { color:var(--muted); margin:0 0 24px; }

.saver { display:flex; gap:10px; margin-bottom:6px; }
.saver input { flex:1; padding:13px 15px; font-size:15px; border:1px solid var(--line);
  border-radius:10px; background:var(--card); outline:none; }
.saver input:focus { border-color:var(--accent); }
.saver input.bad { border-color:#e0857f; background:#fdf3f2; }
button { font:inherit; cursor:pointer; }
button.primary { padding:0 20px; font-size:15px; font-weight:600; color:#fff;
  background:var(--accent); border:none; border-radius:10px; }
button.line { border:1px solid var(--line); background:#fff; color:var(--ink); border-radius:8px; padding:6px 12px; font-size:13px; }
button.line:hover { border-color:#cdd3db; }
.inlineerr { color:var(--danger); font-size:13px; margin:2px 0 0; min-height:18px; }
.savetoread { display:flex; align-items:center; gap:7px; color:var(--muted); font-size:13px; margin:2px 0 16px; }

.searchwrap { position:relative; margin-bottom:16px; }
.searchwrap .ic { position:absolute; left:14px; top:50%; transform:translateY(-50%); color:var(--muted); }
.searchwrap input { width:100%; padding:11px 38px 11px 40px; font-size:14.5px; border:1px solid var(--line);
  border-radius:10px; background:#fbfcfe; outline:none; }
.searchwrap input:focus { border-color:var(--accent); background:#fff; }
.searchwrap .clr { position:absolute; right:10px; top:50%; transform:translateY(-50%); border:none;
  background:none; color:var(--muted); font-size:18px; display:none; }

.bars { display:flex; justify-content:space-between; align-items:flex-start; gap:12px; flex-wrap:wrap; margin-bottom:6px; }
.filterbar { display:flex; flex-wrap:wrap; gap:8px; align-items:center; flex:1; min-width:0; }
.fb { border:1px solid var(--line); background:#fff; color:var(--chipink); border-radius:999px;
  padding:6px 13px; font:inherit; font-size:13px; }
.fb:hover { border-color:#cdd3db; }
.fb.on { background:var(--accent); border-color:var(--accent); color:#fff; }
.fb.toread { border-color:#d9c68a; color:#8a6d1f; font-weight:600; }
.fb.toread.on { background:#caa93f; border-color:#caa93f; color:#fff; }
.fb.away.on { background:#6b7480; border-color:#6b7480; color:#fff; }
.fb .n { opacity:.6; margin-left:5px; }
.fb .sep { display:inline-block; }
.sep { width:1px; height:20px; background:var(--line); }
.sortwrap { display:flex; align-items:center; gap:8px; color:var(--muted); font-size:13px; }
.sortwrap select { font:inherit; font-size:13px; border:1px solid var(--line); border-radius:8px; padding:6px 8px; background:#fff; color:var(--ink); }

.statusline { color:var(--muted); font-size:13px; margin:8px 0 12px; min-height:18px; }
.statusline b { color:var(--ink); } .statusline a { color:var(--accent); cursor:pointer; }
.notice { background:#eef3ff; border:1px solid #d4e0ff; border-radius:10px; padding:10px 14px;
  font-size:13.5px; margin:0 0 14px; display:none; }

.list { list-style:none; margin:0; padding:0; }
li.item { background:var(--card); border:1px solid var(--line); border-radius:12px;
  padding:14px 16px; margin-bottom:10px; display:flex; gap:12px; align-items:flex-start;
  transition:background .3s,border-color .3s,opacity .3s,transform .3s; }
li.item.flash { background:var(--flash); border-color:#f0e3a8; }
li.item.leaving { opacity:0; transform:translateX(12px); }
li.item.away { background:#f4f5f7; }
li.item.needsname { border-color:#eacf9e; background:#fffdf7; }

.readck { flex:none; width:22px; height:22px; margin-top:5px; border-radius:50%;
  border:2px solid #cfd6df; background:#fff; display:grid; place-items:center; color:#fff; font-size:13px; padding:0; }
.readck:hover { border-color:var(--read); }
.readck.done { background:var(--read); border-color:var(--read); }
.readck.spacer { visibility:hidden; }

.favicon { width:32px; height:32px; border-radius:8px; flex:none; background:#eef1f6; display:grid; place-items:center; font-size:16px; }
.body { min-width:0; flex:1; }
.title { font-weight:600; font-size:15.5px; margin:0 0 2px; word-wrap:break-word; }
.title a { color:var(--ink); text-decoration:none; } .title a:hover { text-decoration:underline; }
.title .raw { word-break:break-all; }
.item.isread .title a { color:var(--muted); }
.desc { color:var(--muted); font-size:13.5px; margin:0 0 6px; }
.note { background:var(--notebg); border-left:3px solid #e4d29a; color:var(--note); border-radius:0 8px 8px 0;
  padding:6px 10px; font-size:13px; margin:0 0 6px; white-space:pre-wrap; overflow-wrap:anywhere; }
.note .lbl { font-size:11px; text-transform:uppercase; letter-spacing:.04em; opacity:.7; display:block; margin-bottom:1px; }
.note .expand { color:var(--accent); cursor:pointer; margin-left:4px; }
.meta { color:var(--muted); font-size:12.5px; margin:0 0 6px; }
.warnnote { display:inline-flex; gap:6px; background:var(--warnbg); color:var(--warn); border-radius:8px; padding:4px 10px; font-size:12.5px; }
.badges { display:flex; flex-wrap:wrap; gap:6px; align-items:center; }
.lchip { background:var(--chip); color:var(--chipink); border-radius:999px; padding:3px 10px; font-size:12.5px; border:1px solid transparent; }
.lchip:hover { border-color:#cdd3db; cursor:pointer; }
.state { font-size:12px; border-radius:999px; padding:2px 9px; }
.state.toread { background:#fdf3d6; color:#8a6d1f; } .state.read { background:#e6f4ea; color:var(--read); }
.state.away { background:#e3e5e9; color:#5b636e; }
mark { background:var(--mark); border-radius:3px; padding:0 1px; }

.actions { flex:none; display:flex; flex-direction:column; gap:6px; align-items:stretch; }
.btn { border:1px solid var(--line); background:#fff; color:var(--muted); border-radius:8px; padding:5px 11px; font-size:13px; white-space:nowrap; }
.btn:hover { border-color:#cdd3db; color:var(--ink); }
.btn.fix { border-color:#eacf9e; color:var(--warn); }

.spinner { width:16px; height:16px; border:2px solid var(--line); border-top-color:var(--accent);
  border-radius:50%; animation:spin .7s linear infinite; }
@keyframes spin { to { transform:rotate(360deg); } }

/* edit / manage panel */
.editform { flex:1; }
.editform label { display:block; font-size:12px; color:var(--muted); margin:8px 0 3px; }
.editform label:first-child { margin-top:0; }
.field { width:100%; font:inherit; color:var(--ink); border:1px solid var(--accent); border-radius:6px; padding:6px 8px; outline:none; }
textarea.field { resize:vertical; min-height:44px; }
.labelbox { border:1px solid var(--accent); border-radius:6px; padding:6px; }
.labelbox .chips { display:flex; flex-wrap:wrap; gap:6px; align-items:center; }
.echip { background:var(--chip); color:var(--chipink); border-radius:999px; padding:3px 6px 3px 10px; font-size:12.5px; display:inline-flex; align-items:center; gap:4px; }
.echip button { border:none; background:none; color:var(--muted); font-size:14px; line-height:1; padding:0 2px; }
.echip button:hover { color:var(--danger); }
.labelinput { border:none; outline:none; font:inherit; padding:4px; min-width:130px; flex:1; }
.suggest { position:relative; }
.suggest .drop { position:absolute; left:0; right:0; top:4px; background:#fff; border:1px solid var(--line);
  border-radius:8px; box-shadow:0 6px 20px rgba(0,0,0,.12); padding:5px; z-index:5; max-height:220px; overflow:auto; }
.suggest .drop button { display:flex; width:100%; justify-content:space-between; align-items:center; text-align:left;
  border:none; background:none; padding:8px 10px; border-radius:7px; color:var(--ink); }
.suggest .drop button:hover { background:#f2f4f8; }
.suggest .drop .tag { color:var(--muted); font-size:12px; } .suggest .drop .create { color:var(--accent); }
.formbtns { margin-top:12px; display:flex; gap:8px; align-items:center; }
.formbtns .done { background:var(--accent); color:#fff; border:none; border-radius:8px; padding:8px 16px; font-weight:600; }
.formbtns .cancel { background:none; border:none; color:var(--muted); padding:8px 6px; }
.formbtns .cancel:hover { color:var(--ink); text-decoration:underline; }
.mgmt { margin-top:14px; padding-top:12px; border-top:1px dashed var(--line); display:flex; gap:10px; align-items:center; }
.mgmt .away { border:1px solid var(--line); background:#fff; color:#5b636e; border-radius:8px; padding:7px 12px; }
.mgmt .mgmtnote { font-size:12px; color:var(--muted); }
.mgmt .del { border:1px solid #eecbc6; background:#fff; color:var(--danger); border-radius:8px; padding:7px 12px; margin-left:auto; }
.mgmt .del:hover { background:#fdf3f2; }

.empty { text-align:center; color:var(--muted); padding:44px 20px; border:1px dashed var(--line); border-radius:14px; }
.empty .big { font-size:17px; color:var(--ink); margin-bottom:6px; }
.empty .celebrate { color:var(--read); font-size:17px; }
.more { text-align:center; color:var(--muted); font-size:13px; padding:10px; }

/* import dialog */
.overlay { position:fixed; inset:0; background:rgba(20,26,40,.4); display:grid; place-items:center; z-index:30; padding:20px; }
.dialog { background:#fff; border-radius:16px; padding:24px; max-width:560px; width:100%; max-height:86vh; overflow:auto; box-shadow:0 20px 60px rgba(0,0,0,.3); }
.dialog h3 { margin:0 0 4px; font-size:18px; } .dialog .lead { color:var(--muted); margin:0 0 16px; }
.drop { border:2px dashed #cdd6e2; border-radius:12px; padding:26px; text-align:center; color:var(--muted); }
.drop .big { font-size:16px; color:var(--ink); margin-bottom:4px; }
.dialog .row { display:flex; gap:10px; flex-wrap:wrap; margin-top:16px; }
.promises { list-style:none; margin:0 0 16px; padding:0; }
.promises li { padding:9px 0; border-bottom:1px solid var(--line); display:flex; gap:10px; align-items:flex-start; }
.promises li:last-child { border-bottom:none; }
.promises .tick { color:var(--read); font-weight:700; } .promises b { color:var(--ink); }
.labelmap { display:flex; flex-wrap:wrap; gap:6px; margin-top:6px; }
.progress { height:12px; background:#eef1f6; border-radius:999px; overflow:hidden; margin:6px 0; }
.progress > div { height:100%; width:0; background:var(--accent); transition:width .12s linear; }
.ghost { background:#eef1f6; border:none; border-radius:10px; padding:11px 18px; font-weight:600; }

.toast { position:fixed; left:50%; bottom:26px; transform:translateX(-50%); background:#1c2330; color:#fff;
  border-radius:12px; padding:12px 18px; display:none; align-items:center; gap:18px; box-shadow:0 8px 30px rgba(0,0,0,.25); z-index:40; }
.toast button { background:none; border:none; color:#8db4ff; font-weight:600; }

